                    f"{layer_count} layers"
                )
            if replaced_hidden != set(range(delta_hc)):
                raise CheckpointError("delta introduces hidden state incompletely")
        self.hidden_count = delta_hc
        self.pending = delta_pending

    def document(self):
        applied = {
            "tensors": self.tensors,
            "pending": self.pending,
            "_hc": self.hidden_count,
        }
        return _assemble(self.basis, applied)


def _read_segment_raw(store, name, position):
    """Read a chain segment, turning an absent file into a located error."""
    try:
        return store.read_segment(name)
    except FileNotFoundError:
        what = "basis segment 0" if position == 0 else f"delta segment {position}"
        raise CheckpointError(f"chain validation failed at {what}: segment file is missing") from None


def _walk_chain(store, head, basis_reader=None):
    """Assemble the chain ``0..head``; returns the full state document."""
    if basis_reader is None:
        basis_reader = lambda position: _read_segment_raw(store, name_for(position))  # noqa: E731
    walker = _ChainWalker(store.read_segment(_segment_name(_BASIS_INDEX)))
    for index in range(1, head + 1):
        raw = store.read_segment(_segment_name(index))
        walker.apply_delta(index, raw)
    return walker.document()


def _load_chain_store(store, head):
    walker = _ChainWalker(
        _read_segment_raw(store, _segment_name(_BASIS_INDEX), _BASIS_INDEX)
    )
    for index in range(1, head + 1):
        raw = _read_segment_raw(store, _segment_name(index), index)
        walker.apply_delta(index, raw)
    return walker.document()

